#!/usr/bin/env python3
"""
remotion_setup.py — write the Remotion project into remotion/ and install it.

The motion-design layer lives here. Rather than scattering a dozen small
React files across the repo (and hoping every one of them lands in the right
folder), the whole project is carried inside this single file and written out
at render time. One file to place, nothing to misname.

Remotion renders each frame in a headless browser, so it is far slower than
ffmpeg — about 27x slower than real time on a two-core runner. That is why we
only ever render the OVERLAY through it: a few seconds of transparent graphics
that ffmpeg then composites over footage it cut itself. Rendering the whole
video this way would take hours.

Usage:
  python3 scripts/remotion_setup.py        # write files + npm install
Returns non-zero if the install fails, so the caller can fall back.
"""
import json, os, shutil, subprocess, sys

BASE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
ROOT = os.path.join(BASE, "remotion")

FILES = {
 "package.json": "{\n  \"name\": \"ktl-remotion\",\n  \"private\": true,\n  \"version\": \"1.0.0\",\n  \"scripts\": { \"render\": \"remotion render\" },\n  \"dependencies\": {\n    \"@remotion/cli\": \"4.0.512\",\n    \"react\": \"19.0.0\",\n    \"react-dom\": \"19.0.0\",\n    \"remotion\": \"4.0.512\"\n  },\n  \"devDependencies\": { \"@types/react\": \"19.0.0\", \"typescript\": \"5.6.3\" }\n}\n",
 "tsconfig.json": "{\n  \"compilerOptions\": {\n    \"target\": \"ES2018\",\n    \"module\": \"ESNext\",\n    \"jsx\": \"react-jsx\",\n    \"strict\": true,\n    \"moduleResolution\": \"bundler\",\n    \"noEmit\": true,\n    \"esModuleInterop\": true,\n    \"skipLibCheck\": true,\n    \"lib\": [\"DOM\", \"ES2018\"]\n  },\n  \"include\": [\"src\", \"remotion.config.ts\"]\n}\n",
 "remotion.config.ts": "import { Config } from \"@remotion/cli/config\";\nConfig.setVideoImageFormat(\"png\");\nConfig.setPixelFormat(\"yuva420p\");\nConfig.setCodec(\"vp8\");\n",
 "src/index.ts": "import { registerRoot } from \"remotion\";\nimport { RemotionRoot } from \"./Root\";\nregisterRoot(RemotionRoot);\n",
 "src/Root.tsx": "import React from \"react\";\nimport { Composition } from \"remotion\";\nimport { HookPages } from \"./HookPages\";\nimport { Motion } from \"./Motion\";\n\nexport const RemotionRoot: React.FC = () => (\n  <>\n    <Composition\n      id=\"HookPages\"\n      component={HookPages}\n      durationInFrames={9 * 24}\n      fps={24}\n      width={1920}\n      height={1080}\n      defaultProps={{\n        pages: [{ text: \"THE SILENCE\", at: 0.3 }],\n        accent: [245, 132, 38] as [number, number, number],\n      }}\n    />\n    <Composition\n      id=\"Motion\"\n      component={Motion}\n      durationInFrames={8 * 24}\n      fps={24}\n      width={1920}\n      height={1080}\n      defaultProps={{\n        style: \"sweep\",\n        seed: 1,\n        primary: [245, 132, 38] as [number, number, number],\n        secondary: [0, 107, 182] as [number, number, number],\n        ink: [10, 16, 38] as [number, number, number],\n      }}\n    />\n  </>\n);\n",
 "src/HookPages.tsx": "import React from \"react\";\nimport {\n  AbsoluteFill, interpolate, spring, staticFile, useCurrentFrame,\n  useVideoConfig,\n} from \"remotion\";\n\nexport type Page = { text: string; at: number; hold?: number };\nexport type Props = {\n  pages: Page[];\n  accent: [number, number, number];\n  paper?: [number, number, number];\n  ink?: [number, number, number];\n};\n\nconst rgb = (c: [number, number, number]) => `rgb(${c[0]},${c[1]},${c[2]})`;\n\n/**\n * A Vox-style page: it does not slide, it ARRIVES. The spring overshoots a\n * little and settles, the card enters at an angle and straightens as it lands,\n * and it leaves faster than it came. That asymmetry is what makes motion feel\n * designed rather than tweened.\n */\nconst PageCard: React.FC<{ page: Page; index: number; accent: string;\n  paper: string; ink: string }> = ({ page, index, accent, paper, ink }) => {\n  const frame = useCurrentFrame();\n  const { fps, width, height } = useVideoConfig();\n\n  const start = Math.round(page.at * fps);\n  const hold = Math.round((page.hold ?? 1.25) * fps);\n  const local = frame - start;\n  if (local < -2 || local > hold + fps) return null;\n\n  const fromLeft = index % 2 === 0;\n  const enter = spring({\n    frame: local, fps,\n    config: { damping: 14, mass: 0.7, stiffness: 130 },\n  });\n  // the exit is a fast ease-out, not a spring — leaving should feel decisive\n  const exit = interpolate(local, [hold, hold + fps * 0.34], [0, 1],\n    { extrapolateLeft: \"clamp\", extrapolateRight: \"clamp\" });\n\n  const offscreen = width * 0.62;\n  const x = interpolate(enter, [0, 1], [fromLeft ? -offscreen : offscreen, 0])\n    + exit * (fromLeft ? -offscreen * 0.7 : offscreen * 0.7);\n  const rot = interpolate(enter, [0, 1], [fromLeft ? -7 : 7, 0]) + exit * 4;\n  const opacity = Math.min(enter * 1.4, 1) * (1 - exit);\n  const scale = interpolate(enter, [0, 1], [0.88, 1]);\n\n  // three lanes so two cards can share the screen without colliding\n  const lane = 0.22 + 0.19 * (index % 3);\n\n  return (\n    <AbsoluteFill style={{ justifyContent: \"flex-start\", alignItems: fromLeft ? \"flex-start\" : \"flex-end\" }}>\n      <div style={{\n        marginTop: height * lane,\n        marginLeft: fromLeft ? width * 0.07 : 0,\n        marginRight: fromLeft ? 0 : width * 0.07,\n        transform: `translateX(${x}px) rotate(${rot}deg) scale(${scale})`,\n        opacity,\n        display: \"flex\",\n        background: paper,\n        boxShadow: \"0 18px 60px rgba(0,0,0,0.55)\",\n        borderRadius: 4,\n        overflow: \"hidden\",\n        maxWidth: width * 0.62,\n      }}>\n        <div style={{ width: 18, background: accent }} />\n        <div style={{\n          padding: \"30px 52px 34px 44px\",\n          fontFamily: \"HookAnton\",\n          fontSize: 74,\n          lineHeight: 1.06,\n          color: ink,\n          letterSpacing: 0.5,\n          textTransform: \"uppercase\",\n          whiteSpace: \"pre-wrap\",\n        }}>{page.text}</div>\n      </div>\n    </AbsoluteFill>\n  );\n};\n\nexport const HookPages: React.FC<Props> = ({ pages, accent, paper, ink }) => (\n  <AbsoluteFill style={{ backgroundColor: \"transparent\" }}>\n    <style>{`@font-face{font-family:HookAnton;src:url('${staticFile(\"Anton-Regular.ttf\")}') format('truetype');font-display:block;}`}</style>\n    {pages.map((p, i) => (\n      <PageCard key={i} page={p} index={i} accent={rgb(accent)}\n        paper={rgb(paper ?? [246, 247, 250])} ink={rgb(ink ?? [12, 14, 22])} />\n    ))}\n  </AbsoluteFill>\n);\n",
 "src/Motion.tsx": "import React from \"react\";\nimport { AbsoluteFill, interpolate, useCurrentFrame, useVideoConfig } from \"remotion\";\n\nexport type MotionProps = {\n  style: string;\n  seed: number;\n  primary: [number, number, number];\n  secondary: [number, number, number];\n  ink: [number, number, number];\n};\n\nconst rgb = (c: [number, number, number], a = 1) =>\n  `rgba(${c[0]},${c[1]},${c[2]},${a})`;\n\n/** Cheap deterministic pseudo-random: the same seed always draws the same clip. */\nconst rnd = (seed: number, i: number) => {\n  const x = Math.sin(seed * 127.1 + i * 311.7) * 43758.5453;\n  return x - Math.floor(x);\n};\n\n/**\n * These are BACKGROUNDS, not scenes. They are rendered once into a library and\n * then reused across every video, with the day's text laid over them by ffmpeg.\n * That is the whole economic trick: the expensive motion is paid for once.\n *\n * So each one has to (a) look alive for eight seconds, (b) loop without a\n * visible seam, and (c) leave the middle of the frame calm enough for type to\n * sit on it. Anything busy in the centre fights the words.\n */\n\nconst Sweep: React.FC<MotionProps> = ({ seed, primary, secondary }) => {\n  const f = useCurrentFrame();\n  const { durationInFrames: D, width: W, height: H } = useVideoConfig();\n  const p = f / D;\n  return (\n    <AbsoluteFill>\n      {[0, 1, 2, 3].map((i) => {\n        const w = 180 + rnd(seed, i) * 360;\n        const from = -600 - i * 500;\n        const x = from + (W + 1400) * ((p + rnd(seed, i + 9)) % 1);\n        const col = i % 2 ? primary : secondary;\n        return (\n          <div key={i} style={{\n            position: \"absolute\", top: -200, left: x, width: w, height: H + 400,\n            transform: \"rotate(14deg)\", background:\n              `linear-gradient(90deg, ${rgb(col, 0)}, ${rgb(col, 0.16)}, ${rgb(col, 0)})`,\n          }} />\n        );\n      })}\n    </AbsoluteFill>\n  );\n};\n\nconst Grid: React.FC<MotionProps> = ({ seed, primary }) => {\n  const f = useCurrentFrame();\n  const { durationInFrames: D } = useVideoConfig();\n  const shift = (f / D) * 120;\n  return (\n    <AbsoluteFill style={{ perspective: 900 }}>\n      <div style={{\n        position: \"absolute\", inset: \"-40% -20% -10% -20%\",\n        transform: \"rotateX(66deg)\",\n        backgroundImage:\n          `linear-gradient(${rgb(primary, 0.22)} 1px, transparent 1px),` +\n          `linear-gradient(90deg, ${rgb(primary, 0.22)} 1px, transparent 1px)`,\n        backgroundSize: \"120px 120px\",\n        backgroundPosition: `0px ${shift}px`,\n        maskImage: \"linear-gradient(to top, rgba(0,0,0,1), rgba(0,0,0,0) 78%)\",\n        WebkitMaskImage: \"linear-gradient(to top, rgba(0,0,0,1), rgba(0,0,0,0) 78%)\",\n      }} />\n    </AbsoluteFill>\n  );\n};\n\nconst Particles: React.FC<MotionProps> = ({ seed, primary, secondary }) => {\n  const f = useCurrentFrame();\n  const { durationInFrames: D, width: W, height: H } = useVideoConfig();\n  const p = f / D;\n  return (\n    <AbsoluteFill>\n      {Array.from({ length: 46 }, (_, i) => {\n        const depth = 0.25 + rnd(seed, i) * 0.75;           // parallax layers\n        const size = 3 + depth * 9;\n        const x = rnd(seed, i + 50) * W;\n        const y0 = rnd(seed, i + 100) * H;\n        const y = (y0 - p * 260 * depth + H) % H;\n        const col = i % 5 === 0 ? primary : secondary;\n        return (\n          <div key={i} style={{\n            position: \"absolute\", left: x, top: y, width: size, height: size,\n            borderRadius: size, background: rgb(col, 0.15 + depth * 0.4),\n          }} />\n        );\n      })}\n    </AbsoluteFill>\n  );\n};\n\nconst Rings: React.FC<MotionProps> = ({ seed, primary }) => {\n  const f = useCurrentFrame();\n  const { durationInFrames: D, width: W, height: H } = useVideoConfig();\n  const p = f / D;\n  const cx = rnd(seed, 3) < 0.5 ? -120 : W + 120;\n  const cy = rnd(seed, 4) < 0.5 ? -80 : H + 80;\n  return (\n    <AbsoluteFill>\n      {Array.from({ length: 9 }, (_, i) => {\n        const r = 240 + i * 190 + p * 190;\n        return (\n          <div key={i} style={{\n            position: \"absolute\", left: cx - r, top: cy - r,\n            width: r * 2, height: r * 2, borderRadius: \"50%\",\n            border: `2px solid ${rgb(primary, 0.20 - i * 0.017)}`,\n          }} />\n        );\n      })}\n    </AbsoluteFill>\n  );\n};\n\nconst Bars: React.FC<MotionProps> = ({ seed, primary, secondary }) => {\n  const f = useCurrentFrame();\n  const { durationInFrames: D, width: W, height: H } = useVideoConfig();\n  const n = 34;\n  return (\n    <AbsoluteFill style={{ justifyContent: \"flex-end\" }}>\n      <div style={{ display: \"flex\", alignItems: \"flex-end\", gap: 6,\n                    padding: \"0 40px\", height: H * 0.42, opacity: 0.5 }}>\n        {Array.from({ length: n }, (_, i) => {\n          const speed = 0.6 + rnd(seed, i) * 1.8;\n          const h = 0.15 + 0.85 * Math.abs(Math.sin((f / D) * Math.PI * speed + i));\n          return (\n            <div key={i} style={{\n              flex: 1, height: `${h * 100}%`,\n              background: `linear-gradient(to top, ${rgb(i % 3 ? secondary : primary, 0.55)}, ${rgb(primary, 0)})`,\n            }} />\n          );\n        })}\n      </div>\n    </AbsoluteFill>\n  );\n};\n\nconst Court: React.FC<MotionProps> = ({ seed, primary }) => {\n  const f = useCurrentFrame();\n  const { durationInFrames: D, width: W, height: H } = useVideoConfig();\n  const p = f / D;\n  const dash = 1400;\n  return (\n    <AbsoluteFill style={{ opacity: 0.55 }}>\n      <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`}>\n        <g stroke={rgb(primary, 0.35)} fill=\"none\" strokeWidth={3}>\n          <rect x={140} y={120} width={W - 280} height={H - 240} />\n          <line x1={W / 2} y1={120} x2={W / 2} y2={H - 120} />\n          <circle cx={W / 2} cy={H / 2} r={150} />\n          <path d={`M 140 ${H / 2 - 320} A 330 330 0 0 1 140 ${H / 2 + 320}`} />\n          <path d={`M ${W - 140} ${H / 2 - 320} A 330 330 0 0 0 ${W - 140} ${H / 2 + 320}`} />\n        </g>\n        <path d={`M ${W * 0.2} ${H * 0.75} Q ${W * 0.5} ${H * 0.2} ${W * 0.8} ${H * 0.6}`}\n          stroke={rgb(primary, 0.9)} strokeWidth={6} fill=\"none\"\n          strokeDasharray={dash} strokeDashoffset={dash - dash * Math.min(1, p * 1.6)} />\n      </svg>\n    </AbsoluteFill>\n  );\n};\n\nconst Halftone: React.FC<MotionProps> = ({ seed, primary }) => {\n  const f = useCurrentFrame();\n  const { durationInFrames: D } = useVideoConfig();\n  const p = f / D;\n  return (\n    <AbsoluteFill style={{\n      backgroundImage: `radial-gradient(${rgb(primary, 0.30)} 2px, transparent 2px)`,\n      backgroundSize: \"34px 34px\",\n      backgroundPosition: `${p * 34}px ${p * -34}px`,\n      maskImage: `radial-gradient(circle at ${30 + p * 40}% 50%, rgba(0,0,0,1), rgba(0,0,0,0) 70%)`,\n      WebkitMaskImage: `radial-gradient(circle at ${30 + p * 40}% 50%, rgba(0,0,0,1), rgba(0,0,0,0) 70%)`,\n    }} />\n  );\n};\n\nconst Blobs: React.FC<MotionProps> = ({ seed, primary, secondary }) => {\n  const f = useCurrentFrame();\n  const { durationInFrames: D, width: W, height: H } = useVideoConfig();\n  const p = f / D;\n  return (\n    <AbsoluteFill>\n      {Array.from({ length: 5 }, (_, i) => {\n        const r = 420 + rnd(seed, i) * 420;\n        const x = W * (0.1 + rnd(seed, i + 7) * 0.8) + Math.sin(p * Math.PI * 2 + i) * 90;\n        const y = H * (0.1 + rnd(seed, i + 14) * 0.8) + Math.cos(p * Math.PI * 2 + i) * 70;\n        const col = i % 2 ? primary : secondary;\n        return (\n          <div key={i} style={{\n            position: \"absolute\", left: x - r, top: y - r, width: r * 2, height: r * 2,\n            borderRadius: \"50%\",\n            background: `radial-gradient(circle, ${rgb(col, 0.20)}, ${rgb(col, 0)} 68%)`,\n          }} />\n        );\n      })}\n    </AbsoluteFill>\n  );\n};\n\nconst STYLES: Record<string, React.FC<MotionProps>> = {\n  sweep: Sweep, grid: Grid, particles: Particles, rings: Rings,\n  bars: Bars, court: Court, halftone: Halftone, blobs: Blobs,\n};\n\nexport const Motion: React.FC<MotionProps> = (props) => {\n  const Body = STYLES[props.style] ?? Sweep;\n  const { ink, secondary } = props;\n  const f = useCurrentFrame();\n  const { durationInFrames: D } = useVideoConfig();\n  // fade the very first and last frames so any two clips can be butt-joined\n  const edge = interpolate(f, [0, 6, D - 6, D - 1], [0, 1, 1, 0],\n    { extrapolateLeft: \"clamp\", extrapolateRight: \"clamp\" });\n  // A slow camera move over the whole plate. Some of these patterns are calm\n  // by design — a court diagram barely changes — and a background that does\n  // not move at all reads as a frozen image behind the voice. This guarantees\n  // every clip in the library breathes, whatever is drawn on it.\n  const dir = props.seed % 2 ? 1 : -1;\n  const zoom = 1.05 + 0.05 * (f / D);\n  const driftX = dir * (f / D - 0.5) * 46;\n  const driftY = -dir * (f / D - 0.5) * 26;\n  return (\n    <AbsoluteFill style={{\n      background: `radial-gradient(120% 100% at 50% 0%, ${rgb(secondary, 0.35)}, ${rgb(ink)} 62%)`,\n    }}>\n      <AbsoluteFill style={{\n        opacity: edge,\n        transform: `scale(${zoom}) translate(${driftX}px, ${driftY}px)`,\n      }}>\n        <Body {...props} />\n      </AbsoluteFill>\n      <AbsoluteFill style={{\n        background: \"radial-gradient(70% 60% at 50% 50%, rgba(0,0,0,0) 40%, rgba(0,0,0,0.45))\",\n      }} />\n    </AbsoluteFill>\n  );\n};\n"
}

def write():
    for rel, text in FILES.items():
        path = os.path.join(ROOT, rel)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w") as f:
            f.write(text)
    # the font the cards are set in — reuse the one the rest of the pipeline
    # already ships rather than carrying a second copy in the repo
    pub = os.path.join(ROOT, "public")
    os.makedirs(pub, exist_ok=True)
    src = os.path.join(BASE, "assets", "Anton-Regular.ttf")
    if os.path.exists(src):
        shutil.copy(src, os.path.join(pub, "Anton-Regular.ttf"))
    else:
        raise FileNotFoundError("assets/Anton-Regular.ttf is missing")


def install():
    if os.path.isdir(os.path.join(ROOT, "node_modules", "remotion")):
        print("[remotion] already installed")
        return
    print("[remotion] npm install …", flush=True)
    subprocess.run(["npm", "install", "--no-audit", "--no-fund",
                    "--loglevel=error"], cwd=ROOT, check=True)


def main():
    write()
    install()
    print(f"[remotion] ready at {ROOT}")


if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        print(f"[remotion] setup failed ({e})")
        sys.exit(1)
